#include <bits/stdc++.h>
using namespace std;

using lli = long long;
constexpr int NODE_LIMIT = 5007;
constexpr lli LARGE_NUM = 1000000000LL;
constexpr lli MODULO = 1000000007LL;

struct Link {
    int origin;
    int destination;
    lli capacity;
    lli charge;
    lli utilization;
    Link(int o, int d, lli cap, lli chrge)
        : origin(o), destination(d), capacity(cap), charge(chrge), utilization(0) {}
};

vector<Link> edges;
lli dist_array[NODE_LIMIT];
lli phi_array[NODE_LIMIT];
vector<int> neighbor_list[NODE_LIMIT];
int parent_edge[NODE_LIMIT];

void connect(int u, int v, lli cap, lli cost) {
    neighbor_list[u].push_back(edges.size());
    edges.emplace_back(u, v, cap, cost);
    neighbor_list[v].push_back(edges.size());
    edges.emplace_back(v, u, 0, -cost);
}

void setup_potentials(int source, int steps) {
    fill(phi_array, phi_array + NODE_LIMIT, LARGE_NUM);
    phi_array[source] = 0;
    for (int pass = 0; pass < steps; ++pass) {
        for (size_t k = 0; k < edges.size(); ++k) {
            auto& e = edges[k];
            if (e.capacity == e.utilization) continue;
            if (phi_array[e.origin] == LARGE_NUM) continue;
            phi_array[e.destination] = min(phi_array[e.destination], phi_array[e.origin] + e.charge);
        }
    }
}

void update_distances(int source) {
    fill(dist_array, dist_array + NODE_LIMIT, LARGE_NUM);
    dist_array[source] = 0;
    set<pair<lli, int>> q;
    q.insert({0, source});
    while (!q.empty()) {
        auto [cur_dist, u] = *q.begin();
        q.erase(q.begin());
        for (int eid : neighbor_list[u]) {
            auto& e = edges[eid];
            if (e.capacity == e.utilization) continue;
            int v = e.destination;
            lli cost = e.charge + phi_array[u] - phi_array[v];
            if (dist_array[u] + cost < dist_array[v]) {
                q.erase({dist_array[v], v});
                dist_array[v] = dist_array[u] + cost;
                parent_edge[v] = eid;
                q.insert({dist_array[v], v});
            }
        }
    }
}

pair<lli, lli> min_cost_max_flow(int src, int dst) {
    setup_potentials(src, 50);
    update_distances(src);
    lli total_flow = 0, total_charge = 0;
    while (dist_array[dst] != LARGE_NUM) {
        lli delta = numeric_limits<lli>::max();
        lli path_cost = 0;
        for (int x = dst; x != src; ) {
            int e_id = parent_edge[x];
            delta = min(delta, edges[e_id].capacity - edges[e_id].utilization);
            path_cost += edges[e_id].charge;
            x = edges[e_id].origin;
        }
        total_flow += delta;
        total_charge += delta * path_cost;
        for (int x = dst; x != src; ) {
            int e_id = parent_edge[x];
            edges[e_id].utilization += delta;
            edges[e_id ^ 1].utilization -= delta;
            x = edges[e_id].origin;
        }
        update_distances(src);
        for (int i = 0; i < NODE_LIMIT; ++i) phi_array[i] = dist_array[i];
    }
    return {total_charge, total_flow};
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(20);
    int n, m, k, c_val, d_val;
    cin >> n >> m >> k >> c_val >> d_val;
    vector<int> people(n, 0);
    for (int i = 0; i < k; ++i) {
        int a;
        cin >> a;
        people[--a]++;
    }
    for (int i = 0; i < n; ++i) connect(5000, i, people[i], 0);
    for (int step = 0; step < m; ++step) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        for (int t = 0; t < 99; ++t) {
            lli time_cost = d_val;
            for (int r = 0; r < 50; ++r) {
                connect(u + t * 50, v + (t + 1) * 50, 1, time_cost);
                connect(v + t * 50, u + (t + 1) * 50, 1, time_cost);
                time_cost += 2 * d_val;
            }
        }
    }
    for (int t = 0; t <= 99; ++t) {
        connect(t * 50, 5001, numeric_limits<lli>::max(), c_val * t);
    }
    for (int i = 0; i < n; ++i) {
        for (int t = 0; t < 99; ++t) {
            connect(i + t * 50, i + (t + 1) * 50, numeric_limits<lli>::max(), 0);
        }
    }
    auto [ans, _] = min_cost_max_flow(5000, 5001);
    cout << ans;
    return 0;
}
